sys_ui_page.client_script:
function actionOK() {
    var ga = new GlideAjax('x_1645769_lte_dhlp.ServiceCatalogMarkdownGenerator');
    ga.addParam('sysparm_name', 'attachCatalogItemMarkdown');
    ga.addParam('sysparm_sys_id', $('sc_cat_item').value);
    ga.addParam('sysparm_folder', $('folder').value);
    ga.getXMLAnswer(function(answer) {
		try {
			var result = JSON.parse(answer);
			if (result.success) {
				$('markdown_text').textContent = "Success: Downloading " + result.file_name;
				var downloadUrl = '/sys_attachment.do?sys_id=' + result.sys_id;
				if (typeof g_navigation !== 'undefined')
					g_navigation.open(downloadUrl, '_blank');
				else
					window.open(downloadUrl, '_blank');
			} else
				$('markdown_text').textContent = result.message;
		} catch (e) {
			$('markdown_text').textContent = 'Failed to parse response: ' + e + '\n\nActual resonpse:\n' + JSON.stringify(answer);
		}
    });
    // var ga = new GlideAjax('x_1645769_lte_dhlp.ServiceCatalogMarkdownGenerator');
    // ga.addParam('sysparm_name', 'getCatalogItemMarkdown');
    // ga.addParam('sysparm_sys_id', $('sc_cat_item').value);
    // ga.addParam('sysparm_folder', $('folder').value);
    // ga.getXMLAnswer(function(answer) {
    //     $('markdown_text').textContent = answer;
    // });
}
